-- 0019 P2: signature program journeys + text-free covers (data only, additive).
-- Spec 10 client notes: "give each program a unique and signature way to go through it" and
-- "using imagery that has text in it for card covers is not a good idea".
--
-- 1. programs.meta.journey: per-program journey config read by the course player's journey home
--    (apps/web/src/lib/journey.ts mirrors these values as defaults). Editable in Studio as JSON.
-- 2. programs.meta.cover: focal points (CSS object-position) for wide and phone crops.
-- 3. program_media: covers that were title cards (lettering baked in) now point at text-free
--    photos of Mike in /media/covers/. The title-card files stay in /media/l5e/ (artwork only).
-- No deletes, drops or truncates. Safe to re-run.

update programs set meta = coalesce(meta, '{}'::jsonb) || jsonb_build_object('journey', '{"kind":"skills","theme":"mastery","eyebrow":"Movement mastery · skill tree","promise":"Every kettlebell lift as a skill you unlock: pre-check, technique, common errors, then variations.","unit":{"one":"movement","many":"movements"},"stages":[{"key":"precheck","label":"Pre-check","match":"pre-?check|choosing"},{"key":"errors","label":"Common errors","match":"common errors"},{"key":"variations","label":"Variations","match":"variations"},{"key":"technique","label":"Technique"}],"tiers":[{"label":"Foundations","blurb":"Bells, grips and the positions every lift is built on.","families":[{"group":"Getting Started","label":"Grips & set-up","move":"halo","blurb":"Weights, grips, rack and lockout."}]},{"label":"Grinds","blurb":"Slow strength: hinge, squat, lunge and pull.","families":[{"group":"Deadlift","label":"Deadlift","move":"deadlift","blurb":"The hinge every ballistic lift grows from."},{"group":"Squat","label":"Squat","move":"squat","blurb":"Racked, goblet and box squats."},{"group":"Lunge","label":"Lunge","move":"lunge","blurb":"Forward, reverse and lateral."},{"group":"Row","label":"Row","move":"row","blurb":"Bent-over and supported rows."}]},{"label":"Ballistics","blurb":"Power from the hips: the swing, then the clean.","families":[{"group":"Swing","label":"Swing","move":"swing","blurb":"Russian and pendulum technique."},{"group":"Clean","label":"Clean","move":"clean","blurb":"Into the rack without the forearm bang."}]},{"label":"Overhead","blurb":"Pressing strength and the get-up''s full-body control.","families":[{"group":"Presses and Jerks","label":"Press & jerk","move":"press","blurb":"Strict press, then the jerk."},{"group":"Get Up","label":"Get-up & windmill","move":"getup","blurb":"Turkish get-up, windmill and styles."}]},{"label":"Peak","blurb":"The snatch: everything above, in one lift.","families":[{"group":"Snatch","label":"Snatch","move":"snatch","blurb":"The king of kettlebell lifts."}]}],"shelves":[{"label":"Bonus library","blurb":"Expert talks, program design, posture and benchmarks.","group":"Bonus"}],"pace":{"perWeek":3,"options":[2,3,4,5],"minutes":20,"note":"Short technique sessions between your training days."},"facts":["10 movement families","4 stages each","A plan from your assessment"]}'::jsonb) where slug = 'mastering-the-kettlebell';
update programs set meta = coalesce(meta, '{}'::jsonb) || jsonb_build_object('journey', '{"kind":"blocks","theme":"athletic","eyebrow":"A Suples Training Systems approved program","promise":"Thirty days of Bulgarian bag and kettlebell training in two blocks: build the foundations, then integrate them into performance.","unit":{"one":"day","many":"days"},"path":{"label":"The 30-day program","blurb":"Two training blocks, one day at a time."},"blocks":[{"label":"Get ready","kicker":"Before Day 1","blurb":"Philosophy, schedule, the BOLT test and choosing your bag.","sections":"^getting started$"},{"label":"Block 1 · Foundations","kicker":"Weeks 1–2","blurb":"Learn the spin, arm throw, clean and snatch patterns at a sustainable pace.","sections":"foundations"},{"label":"Block 2 · Performance integration","kicker":"Weeks 3–4 + final days","blurb":"Combine the patterns into complexes and push the work capacity.","sections":"performance integration|final days"}],"shelves":[{"label":"Workout library","blurb":"All seven workouts with level-up and level-down options.","group":"Workout Library"},{"label":"Exercise library","blurb":"Spin, arm throw, clean, snatch and swing squat, move by move.","group":"Exercise Library"},{"label":"Preparation & recovery","blurb":"Mobility, breathing, stretching, Working In and warm-ups.","group":"Preparation & Recovery Series"},{"label":"What''s next","blurb":"Certification, coaching and the Suples system.","group":"What''s Next"},{"label":"Q&A archives","blurb":"Monthly calls from 2025.","group":"2025 Archives"}],"pace":{"perWeek":6,"options":[3,4,5,6],"minutes":40,"note":"The program runs six days a week; train fewer and it simply takes longer."},"artwork":{"src":"/media/covers/a4l-wordmark.png","alt":"A4L Athleticism 4 Life, a Suples Training Systems approved program","width":2000,"height":353},"facts":["30 days","2 training blocks","Bulgarian bag + kettlebell"]}'::jsonb) where slug = 'athleticism-4-life';
update programs set meta = coalesce(meta, '{}'::jsonb) || jsonb_build_object('journey', '{"kind":"series","theme":"calm","eyebrow":"With Paul Chek & Mike Salemi","promise":"Short, energising sessions that put energy back in instead of draining it. Watch one, then practise it on a recovery day.","unit":{"one":"episode","many":"episodes"},"pace":{"perWeek":2,"options":[1,2,3],"minutes":12,"note":"Pairs with every Recovery Day in Kettlebell Lifestyle."},"facts":["Short video series","Calm, low-intensity practice","Pairs with recovery days"]}'::jsonb) where slug = 'working-in';
update programs set meta = coalesce(meta, '{}'::jsonb) || jsonb_build_object('journey', '{"kind":"weeks","theme":"dusk","eyebrow":"Ten weeks of inner work","promise":"One week at a time: the call recording, the playwork and the practice. The journey that became The Grounded King.","unit":{"one":"week","many":"weeks"},"pace":{"perWeek":1,"options":[1,2],"minutes":60,"note":"One week of the program per calendar week, like the live cohort."},"next":{"slug":"the-grounded-king","href":"/programs/the-grounded-king","label":"The Grounded King","reason":"The Path became The Grounded King: the live group that carries this work forward.","cta":"See The Grounded King"},"facts":["10 weeks","Call recordings + playwork","Breath and values practices"]}'::jsonb) where slug = 'the-path-to-inspired-action';
update programs set meta = coalesce(meta, '{}'::jsonb) || jsonb_build_object('journey', '{"kind":"pillars","theme":"earth","eyebrow":"Men of Movement · retreat preparation","promise":"Arrive grounded. Six foundational practices across the five pillars of the retreat, open from about three months before you travel.","unit":{"one":"practice","many":"practices"},"pillars":[{"key":"rotation","label":"Rotation","blurb":"The rotational work you''ll share on the mountain.","move":"halo"},{"key":"movement","label":"Movement","blurb":"Prepare the body: organ prep and the wall squat.","move":"squat","lessons":"abdominal|wall squat"},{"key":"breathwork","label":"Breathwork","blurb":"Piston breathing and Breathe Light.","move":"breathing","lessons":"breath"},{"key":"nature","label":"Nature","blurb":"Listening practice to slow down before you arrive.","move":"walking","lessons":"meditation"},{"key":"storywork","label":"Storywork","blurb":"The books and music that set the tone.","move":"walking","lessons":"book|playlist"}],"pace":{"perWeek":2,"options":[1,2,3],"minutes":20,"note":"Spread the practices across the weeks before the retreat."},"next":{"slug":"men-of-movement-retreats","href":"/experiences","label":"Men of Movement Retreats","reason":"Preparation opens with your retreat place. Hold Your Ground and Primal Reset are by application.","cta":"See the retreats"},"facts":["5 pillars","Included with your retreat","Post-retreat module after the retreat"]}'::jsonb) where slug = 'men-of-movement';
update programs set meta = coalesce(meta, '{}'::jsonb) || jsonb_build_object('journey', '{"kind":"steps","theme":"ember","eyebrow":"Free · the 7-step swing set-up","promise":"The short course Mike sends every new swinger: seven checkpoints from the feet to the grip, three bonuses and a two-week swing program.","unit":{"one":"step","many":"steps"},"pace":{"perWeek":3,"options":[2,3,4],"minutes":10,"note":"One step per session, then the two-week program."},"next":{"slug":"mastering-the-kettlebell","href":"/programs/mastering-the-kettlebell/course","label":"Mastering the Kettlebell","reason":"MTK''s Swing chapter picks up where the set-up ends: Russian and pendulum technique, breathing, and a fix for every common error.","cta":"See the Swing chapter"},"facts":["7 steps","3 bonuses","Free ebook"]}'::jsonb) where slug = 'what-your-kettlebell-swing-is-missing';
update programs set meta = coalesce(meta, '{}'::jsonb) || jsonb_build_object('journey', '{"kind":"steps","theme":"ember","eyebrow":"Free · six videos for trainers","promise":"Six coaching videos that sharpen your eye: the swing''s big mistake, reaction training, bottoms-up pressing, safe snatches and integrated tension.","unit":{"one":"video","many":"videos"},"pace":{"perWeek":3,"options":[2,3,6],"minutes":8,"note":"Watch one before each coaching session this week."},"next":{"slug":"mastering-the-kettlebell","href":"/programs/mastering-the-kettlebell/course","label":"Mastering the Kettlebell","reason":"For coaches: 300+ lessons with pre-checks and common-error fixes you can point clients at.","cta":"See what''s inside"},"facts":["6 videos","For trainers and coaches","Free"]}'::jsonb) where slug = 'free-6-video-kettlebell-mini-series';
update programs set meta = coalesce(meta, '{}'::jsonb) || jsonb_build_object('journey', '{"kind":"route","theme":"ember","eyebrow":"Free · find your phase of training","promise":"Four phases from the foundation to mastery. Find where you are today and train according to your phase.","unit":{"one":"phase","many":"phases"},"next":{"slug":"kettlebell-lifestyle","href":"/programs/kettlebell-lifestyle","label":"Kettlebell Lifestyle","reason":"Know your phase? Kettlebell Lifestyle turns it into a day-by-day plan from the On Ramp to the summit.","cta":"Enter Kettlebell Lifestyle"},"facts":["4 phases","Free"]}'::jsonb) where slug = 'kettlebell-roadmap';

