-- Title-card covers → text-free photos of Mike.
update program_media set url = '/media/covers/mastering-the-kettlebell.jpg', alt = 'Mike Salemi in a racked kettlebell squat'
  where url = '/media/l5e/2c8245bf-d2f2-4483-8be4-dccd5af4dbef/mastering-the-kettlebell.png'
    and program_id = (select id from programs where slug = 'mastering-the-kettlebell');
update program_media set url = '/media/covers/working-in.jpg', alt = 'Paul Chek and Mike Salemi leading a Working In session'
  where url = '/media/l5e/0f8c0c9c-3d88-4297-b30a-2c19e672fb67/working-in.png'
    and program_id = (select id from programs where slug = 'working-in');
update program_media set url = '/media/covers/zen-savage.jpg', alt = 'Mike Salemi in a Turkish get-up'
  where url = '/media/l5e/0f8c0c9c-3d88-4297-b30a-2c19e672fb67/working-in.png'
    and program_id = (select id from programs where slug = 'zen-savage');
-- Coaching cards: Mike coaching (the approved catalog design), the portrait stays as the hero.
update program_media set url = '/media/covers/coaching.jpg', alt = 'Mike Salemi coaching a member through a kettlebell drill'
  where role = 'card' and url = '/media/l5e/801b743d-da63-4eb5-8408-9d98aa8b88ff/coach.jpg'
    and program_id in (select id from programs where slug in ('coaching', 'executive-edge'));
